def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    if n == 1:
        return 'C'
    if n == 2:
        return 'D' if last_opp == 'D' else 'C'

    opp_d = opp.count('D')
    my_d = me.count('D')
    if opp_d == 0:
        return 'C' if n < 99 else 'D'
    if opp_d == n:
        return 'D'

    recent5 = opp[-5:]
    opp_recent_d = recent5.count('D')
    my_recent_d = me[-5:].count('D')
    recent10 = opp[-10:]
    opp_recent10_d = recent10.count('D')

    # strong retaliation: if opponent is in a defection streak, keep defecting
    streak = 0
    for x in reversed(opp):
        if x == 'D':
            streak += 1
        else:
            break
    if streak >= 3:
        return 'D'

    # if we are locked in mutual defection, try to break out sometimes
    my_streak = 0
    for x in reversed(me):
        if x == 'D':
            my_streak += 1
        else:
            break
    if streak >= 2 and my_streak >= 2:
        if n < 95 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # near end: exploit cooperative opponents
    if n >= 94:
        if opp_d <= 2:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if n >= 97:
            return 'D'
        return 'C'

    # if opponent has been very cooperative, stay cooperative but probe once in a while
    if opp_d <= 2:
        if n >= 25 and n % 19 == 0:
            return 'D'
        return 'C'

    # estimate conditional response: D after our C vs C after our C
    opp_after_my_c = 0
    opp_after_my_c_d = 0
    opp_after_my_d = 0
    opp_after_my_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_my_c += 1
            if opp[i + 1] == 'D':
                opp_after_my_c_d += 1
        else:
            opp_after_my_d += 1
            if opp[i + 1] == 'D':
                opp_after_my_d_d += 1
    p_d_after_c = opp_after_my_c_d / opp_after_my_c if opp_after_my_c > 0 else 0.5
    p_d_after_d = opp_after_my_d_d / opp_after_my_d if opp_after_my_d > 0 else 0.5

    # if opponent punishes our defections a lot, cooperate to rebuild
    if p_d_after_d > p_d_after_c + 0.15:
        return 'C'
    # if opponent forgives defections, exploit
    if p_d_after_c > p_d_after_d + 0.25 and n > 20:
        if rng.random() < 0.75:
            return 'D'

    # reciprocate but with limited forgiveness
    if last_opp == 'D':
        if opp_recent_d >= 3:
            return 'D'
        if opp_d * 2 > n:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # last was C
    if opp_recent_d >= 2:
        return 'C'
    if n > 15 and opp_d * 4 < n and rng.random() < 0.05:
        return 'D'
    return 'C'
